const t=[{type:"Past Perfect",vnExamples:["Tôi đã làm xong bài tập trước khi giáo viên đến.","Cô ấy đã ăn sáng trước khi đi làm.","Họ đã rời đi trước khi chúng tôi đến."],usages:[{title:"Cấu trúc",contents:[{point:"S + had + V3/ed",examples:["I had finished.","She had eaten.","They had left."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả một hành động đã hoàn thành trước một hành động khác trong quá khứ.",examples:["I had finished my homework before the teacher arrived.","She had eaten breakfast before going to work."]}]}]},{type:"Relative Clause: 'which'",vnExamples:["Tôi vừa mua một chiếc xe đạp, cái mà rất đắt.","Cô ấy đọc một cuốn sách, cái mà rất thú vị.","Họ xây dựng một ngôi nhà, cái mà rất đẹp."],usages:[{title:"Cấu trúc",contents:[{point:"'which' + mệnh đề phụ",examples:["a bicycle, which is expensive","a book, which is interesting","a house, which is beautiful"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để bổ sung thông tin về một vật hoặc một sự việc đã được nhắc đến trước đó.",examples:["I bought a bicycle, which is expensive.","She read a book, which is interesting."]}]}]},{type:"Relative Clause: 'who'",vnExamples:["Tôi biết một người, người mà rất giỏi trong việc viết lách.","Họ đang nói chuyện với một cô gái, người mà rất thông minh.","Cô ấy có một người bạn, người mà làm việc trong một công ty lớn."],usages:[{title:"Cấu trúc",contents:[{point:"'who' + mệnh đề phụ",examples:["a person, who is good at writing","a girl, who is very smart","a friend, who works in a big company"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để bổ sung thông tin về một người đã được nhắc đến trước đó.",examples:["I know a person, who is good at writing.","They are talking to a girl, who is very smart."]}]}]},{type:"Relative Clause: 'that'",vnExamples:["Đây là chiếc xe mà tôi đã mua.","Cô ấy là người mà tôi ngưỡng mộ.","Đây là ngôi nhà mà chúng tôi xây dựng."],usages:[{title:"Cấu trúc",contents:[{point:"'that' + mệnh đề phụ",examples:["the car that I bought","the person that I admire","the house that we built"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để giới thiệu thông tin cần thiết về một người hoặc vật, thường thay cho 'which' hoặc 'who' trong mệnh đề xác định.",examples:["This is the car that I bought.","She is the person that I admire."]}]}]},{type:"Second Conditional",vnExamples:["Nếu tôi giàu, tôi sẽ đi du lịch vòng quanh thế giới.","Nếu anh ấy chăm chỉ hơn, anh ấy sẽ đạt điểm cao.","Nếu chúng tôi có một chiếc xe, chúng tôi sẽ đến bãi biển."],usages:[{title:"Cấu trúc",contents:[{point:"If + S + V2/ed, S + would + V-inf",examples:["If I were rich, I would travel around the world.","If he worked harder, he would get good grades."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nói về tình huống giả định không có thật ở hiện tại hoặc tương lai.",examples:["If we had a car, we would go to the beach."]}]}]},{type:"Third Conditional",vnExamples:["Nếu tôi đã học chăm chỉ hơn, tôi đã đỗ kỳ thi.","Nếu anh ấy không quên ô, anh ấy đã không bị ướt.","Nếu chúng tôi có thêm thời gian, chúng tôi đã hoàn thành dự án."],usages:[{title:"Cấu trúc",contents:[{point:"If + S + had + V3/ed, S + would have + V3/ed",examples:["If I had studied harder, I would have passed the exam.","If he hadn't forgotten his umbrella, he wouldn't have gotten wet."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nói về tình huống giả định trái ngược với thực tế trong quá khứ.",examples:["If we had had more time, we would have finished the project."]}]}]},{type:"Phrase: 'be used to'",vnExamples:["Tôi đã quen với việc dậy sớm.","Cô ấy đã quen với thời tiết lạnh ở đây.","Họ đã quen với việc sống ở thành phố lớn."],usages:[{title:"Cấu trúc",contents:[{point:"S + be + used to + V-ing/danh từ",examples:["I am used to waking up early.","She is used to the cold weather."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để chỉ thói quen hoặc trạng thái đã quen với điều gì đó.",examples:["They are used to living in a big city."]}]}]},{type:"Phrase: 'used to + V-inf'",vnExamples:["Tôi đã từng chơi bóng đá khi còn nhỏ.","Anh ấy đã từng sống ở London.","Chúng tôi đã từng đi cắm trại mỗi mùa hè."],usages:[{title:"Cấu trúc",contents:[{point:"S + used to + V-inf",examples:["I used to play football.","He used to live in London."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nói về thói quen hoặc trạng thái trong quá khứ mà hiện tại không còn nữa.",examples:["We used to go camping every summer."]}]}]},{type:"Present Perfect",vnExamples:["Tôi đã hoàn thành bài tập của mình.","Cô ấy đã sống ở đây 5 năm.","Họ đã từng đến Nhật Bản."],usages:[{title:"Cấu trúc",contents:[{point:"S + have/has + V3/ed",examples:["I have finished my homework.","She has lived here for 5 years."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả hành động đã hoàn thành tại một thời điểm không xác định trong quá khứ hoặc hành động bắt đầu trong quá khứ và vẫn tiếp diễn đến hiện tại.",examples:["They have been to Japan."]}]}]},{type:"Past Continuous",vnExamples:["Tôi đang học bài khi cô ấy đến.","Anh ấy đang nấu ăn lúc 7 giờ tối qua.","Họ đang chơi bóng khi trời bắt đầu mưa."],usages:[{title:"Cấu trúc",contents:[{point:"S + was/were + V-ing",examples:["I was studying.","He was cooking."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ hoặc hành động đang diễn ra khi một hành động khác xen vào.",examples:["They were playing football when it started to rain."]}]}]},{type:"Conjunction: 'Since'",vnExamples:["Tôi đã không gặp anh ấy kể từ khi tôi rời khỏi thành phố.","Cô ấy đã không ăn gì kể từ khi về nhà.","Chúng tôi đã ở đây kể từ khi trời bắt đầu mưa."],usages:[{title:"Cấu trúc",contents:[{point:"'Since' + mệnh đề hoặc danh từ/cụm danh từ",examples:["Since I left the city, I haven't seen him.","She hasn’t eaten since coming home."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để chỉ thời điểm bắt đầu của một hành động hoặc sự kiện, hoặc lý do cho một hành động.",examples:["We have been here since it started raining."]}]}]},{type:"Conjunction: 'Whereas'",vnExamples:["Tôi thích cà phê, trong khi cô ấy thích trà.","Anh ấy rất trầm lặng, trong khi em gái anh ấy rất sôi nổi.","Họ tập trung vào nghiên cứu, trong khi chúng tôi tập trung vào thực hành."],usages:[{title:"Cấu trúc",contents:[{point:"'Whereas' + mệnh đề",examples:["I like coffee, whereas she prefers tea.","He is quiet, whereas his sister is outgoing."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để so sánh hai ý tưởng hoặc tình huống tương phản.",examples:["They focus on research, whereas we focus on practice."]}]}]},{type:"Connectives: 'Nonetheless'",vnExamples:["Anh ấy cảm thấy mệt mỏi; tuy nhiên, anh ấy vẫn đi làm.","Chúng tôi đã không chuẩn bị kỹ; tuy nhiên, kết quả vẫn tốt.","Cô ấy không có kinh nghiệm; tuy nhiên, cô ấy đã làm rất tốt."],usages:[{title:"Cấu trúc",contents:[{point:"'Nonetheless' + mệnh đề",examples:["He felt tired; nonetheless, he went to work.","We weren’t well-prepared; nonetheless, the results were good."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả sự đối lập hoặc bất chấp điều gì đó đã xảy ra trước đó.",examples:["She had no experience; nonetheless, she did a great job."]}]}]},{type:"Preposition: 'Among'",vnExamples:["Cô ấy ở giữa những người bạn của mình.","Quyển sách nằm giữa các tài liệu.","Anh ấy rất nổi bật giữa đám đông."],usages:[{title:"Cấu trúc",contents:[{point:"'Among' + danh từ số nhiều",examples:["among her friends","among the documents"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để chỉ vị trí ở giữa nhiều người hoặc vật.",examples:["He stood out among the crowd."]}]}]},{type:"Preposition: 'Beneath'",vnExamples:["Con mèo đang nằm dưới ghế.","Họ xây hầm bên dưới ngôi nhà.","Có một tầng hầm bên dưới tòa nhà."],usages:[{title:"Cấu trúc",contents:[{point:"'Beneath' + danh từ",examples:["beneath the chair","beneath the house"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để chỉ vị trí ở phía dưới hoặc thấp hơn vật gì đó.",examples:["There is a basement beneath the building."]}]}]},{type:"Preposition: 'Beyond'",vnExamples:["Ngôi nhà ở phía bên kia ngọn đồi.","Câu hỏi này vượt ngoài khả năng của tôi.","Con đường kéo dài ra xa hơn bìa rừng."],usages:[{title:"Cấu trúc",contents:[{point:"'Beyond' + danh từ",examples:["beyond the hill","beyond my ability"]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để chỉ vị trí xa hơn hoặc vượt qua giới hạn nào đó.",examples:["The road stretches beyond the edge of the forest."]}]}]}];export{t as u};
